1	import ReachyKit
2	import ReachyMedia
3	import SwiftUI
4	
5	/// The call framing's effects, beside `RootLifecycle` rather than inside it —
6	/// that body's own comment says it has no cyclomatic budget left. Everything
7	/// here is inert in previews and on macOS: the controller's facade no-ops off
8	/// iOS, and `previewMode` guards the rest.
9	///
10	/// What it does, in one place:
11	/// - keeps `RobotCallController` pointed at the connected robot;
12	/// - ends the call when the session under it goes away (robot asleep or
13	///   disconnected, stream failed, viewport target gone) — deliberately **not**
14	///   when the stream merely leaves `.streaming`, because `CameraSession`
15	///   self-heals through `.connecting` and the mic track comes back on its own;
16	/// - receives a Recents redial and routes call requests (Siri's included) —
17	///   Live tab, camera content, then unmute once the stream is up;
18	/// - donates the start-call intent each time a call actually starts.
19	struct RootCallLifecycle: ViewModifier {
20	    let session: RobotSession
21	    let viewport: ViewportModel
22	    let router: ReachyRouter
23	    let call: RobotCallController
24	    let remoteLink: RemoteRobotLink?
25	
26	    /// `shared` for the reason `QuickActionInbox.shared` is: the intent that
27	    /// fills it runs with no initialiser to inject through.
28	    private let inbox = CallRequestInbox.shared
29	
30	    @Environment(\.reachyPreviewMode) private var previewMode
31	
32	    func body(content: Content) -> some View {
33	        content
34	            .onChange(of: connectedIdentity, initial: true) { _, identity in
35	                guard !previewMode else { return }
36	                call.robotChanged(id: identity?.deduplicationKey, name: identity?.name)
37	            }
38	            .onChange(of: callMustEnd) { _, mustEnd in
39	                guard !previewMode, mustEnd else { return }
40	                call.sessionBecameIneligible(failed: cameraHasFailed)
41	            }
42	            .onContinueUserActivity(CallActivity.activityType) { activity in
43	                guard !previewMode, let robotID = CallActivity.robotID(from: activity) else { return }
44	                inbox.receive(robotID: robotID)
45	            }
46	            .onChange(of: routingTrigger, initial: true) { _, _ in
47	                guard !previewMode else { return }
48	                routePendingRequest()
49	            }
50	            .onChange(of: call.donationCount) { _, _ in
51	                guard !previewMode, let active = call.activeCall else { return }
52	                CallActivity.donate(robotID: active.robotID, robotName: active.robotName)
53	            }
54	    }
55	
56	    /// The identity through `.unreachable` too: a network blip must not read as
57	    /// a robot change and end the call — the same reading `publishHandoff`
58	    /// makes. Only the phases with no identity at all report none.
59	    private var connectedIdentity: RobotIdentity? {
60	        switch session.phase {
61	        case let .connected(identity), let .unreachable(identity): identity
62	        case .idle, .connecting: nil
63	        }
64	    }
65	
66	    private var viewportTarget: ViewportModel.Source? {
67	        RootViewportTarget.source(session: session, remoteLink: remoteLink)
68	    }
69	
70	    private var cameraHasFailed: Bool {
71	        if case .failed = viewport.cameraSession?.phase {
72	            return true
73	        }
74	        return false
75	    }
76	
77	    private var callMustEnd: Bool {
78	        guard call.hasActiveCall else { return false }
79	        return viewportTarget == nil || !session.isAwake || cameraHasFailed
80	    }
81	
82	    /// Everything a pending request waits on, in one `Equatable` value — the
83	    /// `EntityIndexTrigger` shape. A change to any of them re-runs the routing:
84	    /// the request arriving, the robot connecting, the stream coming up.
85	    private struct RoutingTrigger: Equatable {
86	        let pendingToken: Int?
87	        let robotID: String?
88	        let cameraIsStreaming: Bool
89	    }
90	
91	    private var routingTrigger: RoutingTrigger {
92	        RoutingTrigger(
93	            pendingToken: inbox.pending?.token,
94	            robotID: connectedIdentity?.deduplicationKey,
95	            cameraIsStreaming: viewport.cameraSession?.phase == .streaming
96	        )
97	    }
98	
99	    private func routePendingRequest() {
100	        guard let pending = inbox.pending else { return }
101	        guard !pending.request.isExpired(now: Date()) else {
102	            inbox.drop()
103	            return
104	        }
105	        switch CallRequestRouting.decide(
106	            requestRobotID: pending.request.robotID,
107	            connectedRobotID: connectedIdentity?.deduplicationKey,
108	            connectedRobotName: connectedIdentity?.name
109	        ) {
110	        case .waitForConnection:
111	            // Leave it pending; connecting re-fires the trigger and expiry
112	            // bounds the wait.
113	            break
114	        case .liveTabOnly:
115	            inbox.drop()
116	            router.tab = .live
117	        case .proceed:
118	            router.tab = .live
119	            guard session.hasCamera else {
120	                // A wired unit has no camera and therefore no call to place;
121	                // the Live tab saying so is the whole answer.
122	                inbox.drop()
123	                return
124	            }
125	            if viewport.content != .camera {
126	                viewport.setContent(.camera)
127	            }
128	            guard let camera = viewport.cameraSession, camera.phase == .streaming else {
129	                // Not up yet — the trigger fires again at `.streaming`.
130	                return
131	            }
132	            inbox.drop()
133	            call.startCall(for: camera)
134	        }
135	    }
136	}
